# -*- coding: utf-8 -*-
from pathlib import Path
O=Path(__file__).resolve().parents[2]/'assets/style-a'
data=(O/'models/review-data.json').read_text()
page='''<!doctype html><html lang="zh-CN"><meta charset="utf-8"><title>Space Bend · 三维模型审阅</title><style>*{box-sizing:border-box}body{margin:0;background:#0b1218;color:#eaf2f7;font-family:"PingFang SC","Helvetica Neue",sans-serif;padding:36px}h1{font-size:30px;font-weight:500;margin:0 0 12px}p{font-size:15px;color:#93a9b8}#grid{display:grid;grid-template-columns:repeat(3,1fr);gap:22px;margin-top:30px}article{position:relative;background:#14212a;border-top:1px solid #425f70;padding:18px}canvas{width:100%;height:310px;display:block;cursor:grab;touch-action:none}h2{font-size:18px;font-weight:400;margin:4px 0}small{color:#9ce5f4;letter-spacing:2px}a{color:#9ce5f4;font-size:13px}.note{margin-top:25px}button{color:#eaf2f7;background:#263e4a;border:1px solid #608598;border-radius:0;padding:9px 18px;cursor:pointer}@media(max-width:800px){#grid{grid-template-columns:1fr 1fr}canvas{height:240px}}</style><h1>SPACE BEND / 六种航天传送物体</h1><p>风格 A · 原创程序化 GLB 网格与 PBR 材质 · 拖拽旋转查看 · 审阅稿</p><button id="spin">开始自动旋转</button><div id="grid"></div><p class="note">Y 轴向上 / 米制 / 前方 −Z。此页采用简化灯光查看网格；真实 PICO 材质、比例与设备表现将在第三步验证。模型可分别下载，不含游戏代码。</p><script id="model-data" type="application/json">'''+data+'''</script><script>
const all=JSON.parse(document.getElementById('model-data').textContent), names=['探测机器人','能量核心','小型航天器','微型探测器','重型舱体','信标装置'],ids=['exploration_robot','energy_core','spacecraft','micro_probe','heavy_capsule','beacon'];let spinning=false;
document.getElementById('spin').onclick=()=>{spinning=!spinning;document.getElementById('spin').textContent=spinning?'暂停自动旋转':'开始自动旋转'};
const VS=`#version 300 es
in vec3 position;in vec3 normal;uniform vec3 center;uniform float radius;uniform float yaw;uniform float pitch;uniform float aspect;out vec3 N;out vec3 P;
vec3 rot(vec3 v){float c=cos(yaw),s=sin(yaw);v=vec3(c*v.x+s*v.z,v.y,-s*v.x+c*v.z);c=cos(pitch);s=sin(pitch);return vec3(v.x,c*v.y-s*v.z,s*v.y+c*v.z);}
void main(){vec3 p=rot((position-center)/radius);N=rot(normal);P=p;gl_Position=vec4(p.x/aspect,p.y,-p.z*.2,1.0);}`;
const FS=`#version 300 es
precision highp float;in vec3 N;in vec3 P;uniform vec3 base;uniform vec3 emission;uniform float metallic;uniform float roughness;out vec4 color;
void main(){vec3 n=normalize(N);vec3 l=normalize(vec3(-.6,.9,1.3));vec3 l2=normalize(vec3(1.,.3,-.5));float diffuse=max(dot(n,l),0.);vec3 h=normalize(l+vec3(0,0,1));float spec=pow(max(dot(n,h),0.),mix(100.,12.,roughness));vec3 ambient=base*(.19+.14*(n.y*.5+.5));vec3 lit=ambient+base*diffuse*.85+base*max(dot(n,l2),0.)*.23+mix(vec3(.16),base*.8,metallic)*spec*.85+emission*.38;color=vec4(pow(lit,vec3(.8)),1.);}`;
const scenes=[];
all.forEach((model,k)=>{const art=document.createElement('article');art.innerHTML=`<small>PAYLOAD / 0${k+1}</small><canvas aria-label="${names[k]}三维预览"></canvas><h2>${names[k]}</h2><a href="models/${ids[k]}.glb" download>下载 GLB</a>`;document.getElementById('grid').appendChild(art);const canvas=art.querySelector('canvas');const gl=canvas.getContext('webgl2',{antialias:true,preserveDrawingBuffer:true});if(!gl){art.innerHTML+='<p>当前浏览器无法启用 WebGL 2，请在支持 WebGL 的浏览器中打开。</p>';return}canvas.width=700;canvas.height=620;const prog=gl.createProgram();for(const [type,src] of [[gl.VERTEX_SHADER,VS],[gl.FRAGMENT_SHADER,FS]]){let sh=gl.createShader(type);gl.shaderSource(sh,src);gl.compileShader(sh);if(!gl.getShaderParameter(sh,gl.COMPILE_STATUS))throw Error(gl.getShaderInfoLog(sh));gl.attachShader(prog,sh)}gl.linkProgram(prog);if(!gl.getProgramParameter(prog,gl.LINK_STATUS))throw Error(gl.getProgramInfoLog(prog));gl.useProgram(prog);const g=model.gltf;const bytes=Uint8Array.from(atob(model.bin),c=>c.charCodeAt(0));const meshes=[];let min=[Infinity,Infinity,Infinity],max=[-Infinity,-Infinity,-Infinity];
for(const mesh of g.meshes)for(const p of mesh.primitives){const vao=gl.createVertexArray();gl.bindVertexArray(vao);for(const [key,attrib] of [['POSITION','position'],['NORMAL','normal']]){const a=g.accessors[p.attributes[key]],v=g.bufferViews[a.bufferView],b=gl.createBuffer();gl.bindBuffer(gl.ARRAY_BUFFER,b);gl.bufferData(gl.ARRAY_BUFFER,bytes.subarray(v.byteOffset,v.byteOffset+v.byteLength),gl.STATIC_DRAW);const loc=gl.getAttribLocation(prog,attrib);gl.enableVertexAttribArray(loc);gl.vertexAttribPointer(loc,3,gl.FLOAT,false,0,0);if(key==='POSITION')for(let q=0;q<3;q++){min[q]=Math.min(min[q],a.min[q]);max[q]=Math.max(max[q],a.max[q])}}
const a=g.accessors[p.indices],v=g.bufferViews[a.bufferView],b=gl.createBuffer();gl.bindBuffer(gl.ELEMENT_ARRAY_BUFFER,b);gl.bufferData(gl.ELEMENT_ARRAY_BUFFER,bytes.subarray(v.byteOffset,v.byteOffset+v.byteLength),gl.STATIC_DRAW);meshes.push({vao,count:a.count,mat:g.materials[p.material]})}
const center=min.map((x,i)=>(x+max[i])/2),r=Math.hypot(...min.map((x,i)=>max[i]-x))/2*1.12;const u={};for(const name of ['center','radius','yaw','pitch','aspect','base','emission','metallic','roughness'])u[name]=gl.getUniformLocation(prog,name);let yaw=2.5,pitch=.35,drag=false,last=[0,0];canvas.onpointerdown=e=>{drag=true;last=[e.clientX,e.clientY];canvas.setPointerCapture(e.pointerId)};canvas.onpointerup=()=>drag=false;canvas.onpointermove=e=>{if(drag){yaw+=(e.clientX-last[0])*.01;pitch=Math.max(-1.4,Math.min(1.4,pitch+(e.clientY-last[1])*.01));last=[e.clientX,e.clientY]}};
scenes.push(()=>{if(spinning&&!drag)yaw+=.005;gl.viewport(0,0,canvas.width,canvas.height);gl.clearColor(.078,.129,.165,1);gl.clear(gl.COLOR_BUFFER_BIT|gl.DEPTH_BUFFER_BIT);gl.enable(gl.DEPTH_TEST);gl.useProgram(prog);gl.uniform3fv(u.center,center);gl.uniform1f(u.radius,r);gl.uniform1f(u.yaw,yaw);gl.uniform1f(u.pitch,pitch);gl.uniform1f(u.aspect,canvas.width/canvas.height);for(const m of meshes){const p=m.mat.pbrMetallicRoughness;gl.uniform3fv(u.base,p.baseColorFactor.slice(0,3));gl.uniform3fv(u.emission,m.mat.emissiveFactor||[0,0,0]);gl.uniform1f(u.metallic,p.metallicFactor);gl.uniform1f(u.roughness,p.roughnessFactor);gl.bindVertexArray(m.vao);gl.drawElements(gl.TRIANGLES,m.count,gl.UNSIGNED_INT,0)}})});
function frame(){scenes.forEach(fn=>fn());requestAnimationFrame(frame)}frame();document.body.dataset.modelCount=scenes.length;
</script></html>'''
(O/'models-preview.html').write_text(page)
